1	// Raft 跟随者本地日志复制：在单次命令调用内维护节点状态，顺序应用
2	// 领导者发来的 AppendEntries 请求。本文件只做纯逻辑处理，不连接网络。
3	package mevwatch
4	
5	import "fmt"
6	
7	// LogEntry 是一条日志：Index 从 1 开始连续编号，Term 为该条目写入时的任期，
8	// Command 为字符串命令。
9	type LogEntry struct {
10		Index   int    `json:"index"`
11		Term    int    `json:"term"`
12		Command string `json:"command"`
13	}
14	
15	// InitialState 是跟随者在本次调用开始时的状态。
16	type InitialState struct {
17		// CurrentTerm 是该节点已知的最新任期。
18		CurrentTerm int `json:"currentTerm"`
19		// CommittedIndex 是已经提交（不可覆盖）的最高日志索引。
20		CommittedIndex int `json:"committedIndex"`
21		// Log 是从索引 1 开始的连续日志。
22		Log []LogEntry `json:"log"`
23	}
24	
25	// AppendRequest 是顺序到达的一次日志复制请求。
26	type AppendRequest struct {
27		// Term 是领导者任期。
28		Term int `json:"term"`
29		// PrevLogIndex / PrevLogTerm 是新条目紧邻的前一条日志的索引与任期；
30		// 均为 0 表示日志起点（哨兵），不是真实条目。
31		PrevLogIndex int `json:"prevLogIndex"`
32		PrevLogTerm  int `json:"prevLogTerm"`
33		// Entries 是待追加的条目，必须从前一条索引加 1 开始连续排列，允许为空。
34		Entries []LogEntry `json:"entries"`
35		// LeaderCommit 是领导者已提交索引。
36		LeaderCommit int `json:"leaderCommit"`
37	}
38	
39	// AppendResult 是单条请求处理后节点对该请求的答复。
40	type AppendResult struct {
41		// Accepted 表示本次复制是否成功。
42		Accepted bool `json:"accepted"`
43		// Reason 是成功 ok 或被拒绝的具体原因。
44		Reason string `json:"reason"`
45		// Term 是处理后节点的当前任期（较高任期请求即便最终被拒绝也会留下任期更新）。
46		Term int `json:"term"`
47		// CommittedIndex 是处理后节点的已提交索引。
48		CommittedIndex int `json:"committedIndex"`
49	}
50	
51	// ReplicateOutput 是整次调用的结果。
52	type ReplicateOutput struct {
53		// Results 与输入请求一一对应。
54		Results []AppendResult `json:"results"`
55		// FinalTerm / FinalCommittedIndex 是最终状态。
56		FinalTerm           int `json:"finalTerm"`
57		FinalCommittedIndex int `json:"finalCommittedIndex"`
58		// FinalLog 是处理完所有请求后的完整日志。
59		FinalLog []LogEntry `json:"finalLog"`
60	}
61	
62	// 拒绝原因（稳定标识符，帮助文档中有说明）。
63	const (
64		ReasonOK                      = "ok"
65		ReasonStaleTerm               = "stale term: leader term is lower than current term"
66		ReasonRequestTermNegative     = "invalid request: term is negative"
67		ReasonPrevLogIndexNegative    = "invalid request: prevLogIndex is negative"
68		ReasonPrevLogTermNegative     = "invalid request: prevLogTerm is negative"
69		ReasonLeaderCommitNegative    = "invalid request: leaderCommit is negative"
70		ReasonEmptyEntryTerm          = "invalid request: log entry has zero term"
71		ReasonEntryIndexGap           = "invalid request: entries are not consecutive from prevLogIndex+1"
72		ReasonEntryTermDecreases      = "invalid request: entry terms are not non-decreasing"
73		ReasonEntryTermExceedsReqTerm = "invalid request: entry term exceeds request term"
74		ReasonPrevLogMismatch         = "prev log mismatch: entry at prevLogIndex is missing or has a different term"
75		ReasonCommandConflictSameTerm = "entry conflict: same index and term but different command"
76		ReasonWouldOverwriteCommitted = "would overwrite committed entry"
77	)
78	
79	type replicateState struct {
80		currentTerm    int
81		committedIndex int
82		log            []LogEntry // log[i].Index == i+1
83	}
84	
85	// Replicate 校验初始状态并顺序应用全部复制请求，返回逐次结果与最终状态。
86	// 初始状态非法时返回错误（调用方应以非零退出码结束）。单条请求违反字段规则
87	// 时只记录一次拒绝、不改变任何状态，随后继续处理下一条请求。
88	func Replicate(initial InitialState, requests []AppendRequest) (ReplicateOutput, error) {
89		state, err := newReplicateState(initial)
90		if err != nil {
91			return ReplicateOutput{}, err
92		}
93	
94		results := make([]AppendResult, 0, len(requests))
95		for _, request := range requests {
96			results = append(results, state.apply(request))
97		}
98		finalLog := append([]LogEntry{}, state.log...)
99		if finalLog == nil {
100			finalLog = []LogEntry{}
101		}
102		return ReplicateOutput{
103			Results:             results,
104			FinalTerm:           state.currentTerm,
105			FinalCommittedIndex: state.committedIndex,
106			FinalLog:            finalLog,
107		}, nil
108	}
109	
110	func newReplicateState(initial InitialState) (replicateState, error) {
111		if initial.CurrentTerm < 0 {
112			return replicateState{}, fmt.Errorf("invalid initial state: currentTerm must be a non-negative integer")
113		}
114		if initial.CommittedIndex < 0 {
115			return replicateState{}, fmt.Errorf("invalid initial state: committedIndex must be a non-negative integer")
116		}
117		if initial.CommittedIndex > len(initial.Log) {
118			return replicateState{}, fmt.Errorf("invalid initial state: committedIndex %d exceeds log length %d", initial.CommittedIndex, len(initial.Log))
119		}
120		log := append([]LogEntry(nil), initial.Log...)
121		for i, entry := range log {
122			expected := i + 1
123			if entry.Index != expected {
124				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-consecutive index %d", expected, entry.Index)
125			}
126			if entry.Term <= 0 {
127				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-positive term %d", expected, entry.Term)
128			}
129			if i > 0 && entry.Term < log[i-1].Term {
130				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d is lower than previous term %d", expected, entry.Term, log[i-1].Term)
131			}
132			if entry.Term > initial.CurrentTerm {
133				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d exceeds currentTerm %d", expected, entry.Term, initial.CurrentTerm)
134			}
135		}
136		return replicateState{
137			currentTerm:    initial.CurrentTerm,
138			committedIndex: initial.CommittedIndex,
139			log:            log,
140		}, nil
141	}
142	
143	// termAt 返回索引 idx 处条目的任期；idx 为 0 时是日志起点哨兵，超出日志长度时 ok 为 false。
144	func (s *replicateState) termAt(idx int) (term int, ok bool) {
145		switch {
146		case idx == 0:
147			return 0, true
148		case idx < 0 || idx > len(s.log):
149			return 0, false
150		default:
151			return s.log[idx-1].Term, true
152		}
153	}
154	
155	// apply 处理单条请求。整个操作是原子的：任何拒绝都不会在日志、已提交索引上
156	// 留下部分变更；唯一例外是较高任期带来的 currentTerm 更新，按规则必须保留。
157	func (s *replicateState) apply(request AppendRequest) AppendResult {
158		snapshot := *s
159		accepted, reason := s.tryApply(request)
160		if !accepted {
161			// 回滚日志与提交位置；较高任期更新（若已发生）保留在 s.currentTerm 中。
162			s.log = snapshot.log
163			s.committedIndex = snapshot.committedIndex
164		}
165		return AppendResult{
166			Accepted:       accepted,
167			Reason:         reason,
168			Term:           s.currentTerm,
169			CommittedIndex: s.committedIndex,
170		}
171	}
172	
173	func (s *replicateState) tryApply(request AppendRequest) (bool, string) {
174		// 规则 1：先做字段合法性校验。违反字段规则的请求只记录拒绝、不改变任何
175		// 状态——即使它携带更高任期，也不能更新节点。
176		if reason := validateRequest(request); reason != ReasonOK {
177			return false, reason
178		}
179	
180		// 规则 2：较低任期直接拒绝，状态（含任期）完全不变。
181		if request.Term < s.currentTerm {
182			return false, ReasonStaleTerm
183		}
184	
185		// 规则 3：首条目任期不得低于前一条日志任期（整段日志必须不下降）。
186		// 这仍属于字段规则，放在任期更新之前：非法请求不能借高任期改变节点。
187		if len(request.Entries) > 0 && request.Entries[0].Term < request.PrevLogTerm {
188			return false, ReasonEntryTermDecreases
189		}
190	
191		// 规则 4：较高任期先更新当前任期，再核对日志；之后即便因前缀不匹配被拒，
192		// 任期更新也保留。
193		if request.Term > s.currentTerm {
194			s.currentTerm = request.Term
195		}
196	
197		// 规则 5：前一条日志必须存在且任期相同。索引 0 始终只与任期 0 匹配。
198		prevTerm, ok := s.termAt(request.PrevLogIndex)
199		if !ok || prevTerm != request.PrevLogTerm {
200			return false, ReasonPrevLogMismatch
201		}
202	
203		// 规则 6：把待追加条目与现有位置逐一比对——全部检查通过后才落笔，
204		// 保证“即使前面已发现可追加内容，也不能留下部分变更”。第一个任期冲突
205		// 位置之后的旧日志都会被整段替换，因此只需在冲突位置之前检查命令冲突。
206		// matched 是请求条目中与现有位置完全相同（同任期同命令）的连续前缀长度；
207		// 超出本地日志长度的位置尚不存在，不属于已匹配，稍后追加。
208		start := request.PrevLogIndex // entries[k] 对应索引 start+1+k
209		cutAt := -1                   // 首个任期不同的现有位置（切片下标）
210		matched := 0
211		for offset, incoming := range request.Entries {
212			idx := start + 1 + offset
213			if idx > len(s.log) {
214				break // 该位置及之后都不存在：稍后整体追加
215			}
216			existing := s.log[idx-1]
217			switch {
218			case existing.Term == incoming.Term && existing.Command == incoming.Command:
219				// 完全相同：保留，重复请求不会产生重复条目。
220				matched++
221			case existing.Term == incoming.Term:
222				// 同索引同任期却命令不同：拒绝，日志与提交位置保持原样。
223				return false, ReasonCommandConflictSameTerm
224			case idx <= s.committedIndex:
225				// 不同任期意味着要覆盖该处及其后缀；已提交条目不可覆盖。
226				return false, ReasonWouldOverwriteCommitted
227			default:
228				// 未提交位置上的任期冲突：截断到此处再追加，其后旧日志整段丢弃。
229				cutAt = idx - 1
230			}
231			if cutAt >= 0 {
232				break
233			}
234		}
235	
236		// 规则 7：合并日志。全部匹配的短请求（matched == len(entries)）不删除
237		// 本地多出的尾部；任期冲突时截断冲突位置及其后缀；其余缺失位置追加。
238		if cutAt >= 0 {
239			matched = cutAt - start
240			s.log = append([]LogEntry(nil), s.log[:cutAt]...)
241		}
242		if matched < len(request.Entries) {
243			s.log = append(s.log, request.Entries[matched:]...)
244		}
245	
246		// 规则 8：提交位置推进至 leaderCommit 与本次确认的最后索引的较小值，
247		// 且不会后退。空条目请求的确认位置就是前一条索引。
248		lastIndex := request.PrevLogIndex + len(request.Entries)
249		newCommit := request.LeaderCommit
250		if lastIndex < newCommit {
251			newCommit = lastIndex
252		}
253		if newCommit > s.committedIndex {
254			s.committedIndex = newCommit
255		}
256		return true, ReasonOK
257	}
258	
259	func validateRequest(request AppendRequest) string {
260		if request.Term < 0 {
261			return ReasonRequestTermNegative
262		}
263		if request.PrevLogIndex < 0 {
264			return ReasonPrevLogIndexNegative
265		}
266		if request.PrevLogTerm < 0 {
267			return ReasonPrevLogTermNegative
268		}
269		if request.LeaderCommit < 0 {
270			return ReasonLeaderCommitNegative
271		}
272		// 条目必须从前一条索引加 1 开始连续排列；任期为正、沿请求条目自身
273		// 不下降，且不得超过请求（领导者）任期。与 prevLogTerm 的衔接在
274		// tryApply 中单独检查。索引 0 是哨兵，真实条目索引必为正。
275		for i, entry := range request.Entries {
276			if entry.Index != request.PrevLogIndex+1+i {
277				return ReasonEntryIndexGap
278			}
279			if entry.Term <= 0 {
280				return ReasonEmptyEntryTerm
281			}
282			if i > 0 && entry.Term < request.Entries[i-1].Term {
283				return ReasonEntryTermDecreases
284			}
285			if entry.Term > request.Term {
286				return ReasonEntryTermExceedsReqTerm
287			}
288		}
289		return ReasonOK
290	}
291

