		Accepted:       r.Accepted,
		Reason:         r.Reason,
		Term:           r.Term,
		CommittedIndex: r.CommittedIndex,
		AppliedIndex:   r.AppliedIndex,
		ApplyError:     r.ApplyError,
	})
}

