	if !strings.Contains(body, `"finalApplyError": null`) {
		t.Fatalf("null finalApplyError expected, got: %s", body)
	}
	if !strings.Contains(body, `"applyError": null`) {
		t.Fatalf("null applyError expected, got: %s", body)
