1	// Raft 跟随者本地日志复制：在单次命令调用内维护节点状态，顺序应用
2	// 领导者发来的 AppendEntries 请求。本文件只做纯逻辑处理，不连接网络。
3	package mevwatch
4	
5	import (
6		"encoding/json"
7		"fmt"
8		"strings"
9		"unicode"
10	)
11	
12	// LogEntry 是一条日志：Index 从 1 开始连续编号，Term 为该条目写入时的任期，
13	// Command 为字符串命令。
14	type LogEntry struct {
15		Index   int    `json:"index"`
16		Term    int    `json:"term"`
17		Command string `json:"command"`
18	}
19	
20	// InitialState 是跟随者在本次调用开始时的状态。
21	type InitialState struct {
22		// CurrentTerm 是该节点已知的最新任期。
23		CurrentTerm int `json:"currentTerm"`
24		// CommittedIndex 是已经提交（不可覆盖）的最高日志索引。
25		CommittedIndex int `json:"committedIndex"`
26		// Log 是从索引 1 开始的连续日志。
27		Log []LogEntry `json:"log"`
28		// ApplyKV 为 true 时把已提交命令解释为 set/delete 键值操作；
29		// 为 false（默认）时命令是任意字符串，输出也不包含键值相关字段。
30		ApplyKV bool `json:"applyKV"`
31	}
32	
33	// AppendRequest 是顺序到达的一次日志复制请求。
34	type AppendRequest struct {
35		// Term 是领导者任期。
36		Term int `json:"term"`
37		// PrevLogIndex / PrevLogTerm 是新条目紧邻的前一条日志的索引与任期；
38		// 均为 0 表示日志起点（哨兵），不是真实条目。
39		PrevLogIndex int `json:"prevLogIndex"`
40		PrevLogTerm  int `json:"prevLogTerm"`
41		// Entries 是待追加的条目，必须从前一条索引加 1 开始连续排列，允许为空。
42		Entries []LogEntry `json:"entries"`
43		// LeaderCommit 是领导者已提交索引。
44		LeaderCommit int `json:"leaderCommit"`
45	}
46	
47	// AppendResult 是单条请求处理后节点对该请求的答复。
48	type AppendResult struct {
49		// Accepted 表示本次复制是否成功。
50		Accepted bool `json:"accepted"`
51		// Reason 是成功 ok 或被拒绝的具体原因。
52		Reason string `json:"reason"`
53		// Term 是处理后节点的当前任期（较高任期请求即便最终被拒绝也会留下任期更新）。
54		Term int `json:"term"`
55		// CommittedIndex 是处理后节点的已提交索引。
56		CommittedIndex int `json:"committedIndex"`
57		// AppliedIndex 仅在启用 applyKV 时出现：处理后已应用键值命令的最高日志索引。
58		AppliedIndex int `json:"appliedIndex"`
59		// ApplyError 仅在启用 applyKV 时出现：null 或第一条已提交的格式错误。
60		ApplyError *ApplyError `json:"applyError"`
61	
62		// kvEnabled 控制 JSON 是否包含键值字段，不对外暴露。
63		kvEnabled bool
64	}
65	
66	// ApplyError 描述键值应用过程中遇到的第一条已提交格式错误。
67	type ApplyError struct {
68		// Index 是出错日志条目的索引。
69		Index int `json:"index"`
70		// Reason 是具体的格式问题。
71		Reason string `json:"reason"`
72	}
73	
74	// MarshalJSON 按是否启用 applyKV 输出不同字段集：未启用时与旧输出完全一致。
75	func (r AppendResult) MarshalJSON() ([]byte, error) {
76		if !r.kvEnabled {
77			type plain struct {
78				Accepted       bool   `json:"accepted"`
79				Reason         string `json:"reason"`
80				Term           int    `json:"term"`
81				CommittedIndex int    `json:"committedIndex"`
82			}
83			return json.Marshal(plain{r.Accepted, r.Reason, r.Term, r.CommittedIndex})
84		}
85		type enabled struct {
86			Accepted       bool        `json:"accepted"`
87			Reason         string      `json:"reason"`
88			Term           int         `json:"term"`
89			CommittedIndex int         `json:"committedIndex"`
90			AppliedIndex   int         `json:"appliedIndex"`
91			ApplyError     *ApplyError `json:"applyError"`
92		}
93		return json.Marshal(enabled{
94			Accepted:       r.Accepted,
95			Reason:         r.Reason,
96			Term:           r.Term,
97			CommittedIndex: r.CommittedIndex,
98			AppliedIndex:   r.AppliedIndex,
99			ApplyError:     r.ApplyError,
100		})
101	}
102	
103	// ReplicateOutput 是整次调用的结果。
104	type ReplicateOutput struct {
105		// Results 与输入请求一一对应。
106		Results []AppendResult `json:"results"`
107		// FinalTerm / FinalCommittedIndex 是最终状态。
108		FinalTerm           int `json:"finalTerm"`
109		FinalCommittedIndex int `json:"finalCommittedIndex"`
110		// FinalLog 是处理完所有请求后的完整日志。
111		FinalLog []LogEntry `json:"finalLog"`
112		// FinalAppliedIndex 仅在启用 applyKV 时出现：最终已应用的最高日志索引。
113		FinalAppliedIndex int `json:"finalAppliedIndex"`
114		// FinalKV 仅在启用 applyKV 时出现：最终键值表，空表输出 {}。
115		FinalKV map[string]string `json:"finalKV"`
116		// FinalApplyError 仅在启用 applyKV 时出现：null 或第一条已提交的格式错误。
117		FinalApplyError *ApplyError `json:"finalApplyError"`
118	
119		// kvEnabled 控制 JSON 是否包含键值字段，不对外暴露。
120		kvEnabled bool
121	}
122	
123	// MarshalJSON 按是否启用 applyKV 输出不同字段集：未启用时与旧输出完全一致。
124	func (o ReplicateOutput) MarshalJSON() ([]byte, error) {
125		if !o.kvEnabled {
126			type plain struct {
127				Results             []AppendResult `json:"results"`
128				FinalTerm           int            `json:"finalTerm"`
129				FinalCommittedIndex int            `json:"finalCommittedIndex"`
130				FinalLog            []LogEntry     `json:"finalLog"`
131			}
132			return json.Marshal(plain{o.Results, o.FinalTerm, o.FinalCommittedIndex, o.FinalLog})
133		}
134		type enabled struct {
135			Results             []AppendResult    `json:"results"`
136			FinalTerm           int               `json:"finalTerm"`
137			FinalCommittedIndex int               `json:"finalCommittedIndex"`
138			FinalLog            []LogEntry        `json:"finalLog"`
139			FinalAppliedIndex   int               `json:"finalAppliedIndex"`
140			FinalKV             map[string]string `json:"finalKV"`
141			FinalApplyError     *ApplyError       `json:"finalApplyError"`
142		}
143		return json.Marshal(enabled{
144			Results:             o.Results,
145			FinalTerm:           o.FinalTerm,
146			FinalCommittedIndex: o.FinalCommittedIndex,
147			FinalLog:            o.FinalLog,
148			FinalAppliedIndex:   o.FinalAppliedIndex,
149			FinalKV:             o.FinalKV,
150			FinalApplyError:     o.FinalApplyError,
151		})
152	}
153	
154	// 拒绝原因（稳定标识符，帮助文档中有说明）。
155	const (
156		ReasonOK                      = "ok"
157		ReasonStaleTerm               = "stale term: leader term is lower than current term"
158		ReasonRequestTermNegative     = "invalid request: term is negative"
159		ReasonPrevLogIndexNegative    = "invalid request: prevLogIndex is negative"
160		ReasonPrevLogTermNegative     = "invalid request: prevLogTerm is negative"
161		ReasonLeaderCommitNegative    = "invalid request: leaderCommit is negative"
162		ReasonEmptyEntryTerm          = "invalid request: log entry has zero term"
163		ReasonEntryIndexGap           = "invalid request: entries are not consecutive from prevLogIndex+1"
164		ReasonEntryTermDecreases      = "invalid request: entry terms are not non-decreasing"
165		ReasonEntryTermExceedsReqTerm = "invalid request: entry term exceeds request term"
166		ReasonPrevLogMismatch         = "prev log mismatch: entry at prevLogIndex is missing or has a different term"
167		ReasonCommandConflictSameTerm = "entry conflict: same index and term but different command"
168		ReasonWouldOverwriteCommitted = "would overwrite committed entry"
169	)
170	
171	type replicateState struct {
172		currentTerm    int
173		committedIndex int
174		log            []LogEntry // log[i].Index == i+1
175	}
176	
177	// Replicate 校验初始状态并顺序应用全部复制请求，返回逐次结果与最终状态。
178	// 初始状态非法时返回错误（调用方应以非零退出码结束）。单条请求违反字段规则
179	// 时只记录一次拒绝、不改变任何状态，随后继续处理下一条请求。
180	//
181	// 当初始状态启用 ApplyKV 时，已提交的命令会被解释为 set/delete 键值操作：
182	// 先应用初始日志中已提交的前缀，再在每条请求处理结束后应用新提交且尚未应用
183	// 的条目。已提交命令出现格式错误时，应用停在出错条目之前且本次调用不再继续；
184	// 未提交条目的格式错误不会提前报错。
185	func Replicate(initial InitialState, requests []AppendRequest) (ReplicateOutput, error) {
186		state, err := newReplicateState(initial)
187		if err != nil {
188			return ReplicateOutput{}, err
189		}
190	
191		output := ReplicateOutput{
192			Results:  make([]AppendResult, 0, len(requests)),
193			FinalLog: []LogEntry{},
194		}
195		if initial.ApplyKV {
196			output.kvEnabled = true
197			output.FinalKV = map[string]string{}
198			// 先按索引顺序应用初始日志中已提交的前缀。
199			output.FinalAppliedIndex, output.FinalApplyError =
200				applyCommitted(state.log, state.committedIndex, output.FinalKV, 0)
201		}
202	
203		for _, request := range requests {
204			result := state.apply(request)
205			if initial.ApplyKV {
206				result.kvEnabled = true
207				// 每条请求处理结束后，只应用新提交且尚未应用的日志；
208				// 一旦出错，本次调用的应用状态保持停住。
209				if output.FinalApplyError == nil {
210					output.FinalAppliedIndex, output.FinalApplyError = applyCommitted(
211						state.log, state.committedIndex, output.FinalKV, output.FinalAppliedIndex)
212				}
213				result.AppliedIndex = output.FinalAppliedIndex
214				result.ApplyError = output.FinalApplyError
215			}
216			output.Results = append(output.Results, result)
217		}
218	
219		output.FinalTerm = state.currentTerm
220		output.FinalCommittedIndex = state.committedIndex
221		output.FinalLog = append([]LogEntry{}, state.log...)
222		if output.FinalLog == nil {
223			output.FinalLog = []LogEntry{}
224		}
225		return output, nil
226	}
227	
228	// applyCommitted 顺序应用索引在 (appliedIndex, committedIndex] 内的已提交日志。
229	// 出错时保留此前成功应用的结果，appliedIndex 停在出错条目之前，出错条目及其后
230	// 所有条目都不执行。返回新的已应用最高索引与第一条格式错误（无错误时为 nil）。
231	func applyCommitted(log []LogEntry, committedIndex int, kv map[string]string, appliedIndex int) (int, *ApplyError) {
232		for idx := appliedIndex + 1; idx <= committedIndex; idx++ {
233			if reason, ok := applyCommand(log[idx-1].Command, kv); !ok {
234				return idx - 1, &ApplyError{Index: idx, Reason: reason}
235			}
236			appliedIndex = idx
237		}
238		return appliedIndex, nil
239	}
240	
241	// applyCommand 解析并执行一条键值命令。命令区分大小写，只接受两种形式：
242	//
243	//	set <key>=<value>   写入或覆盖一个键，值以原文保留（可为空、含空格或额外等号）
244	//	delete <key>        删除一个键，删除不存在的键也算成功
245	//
246	// 命令名后必须恰好有一个普通空格；键不能为空，不能含空白或等号；命令两端的
247	// 空白不会被自动去掉。返回的 ok 为 false 时，reason 描述具体的格式问题。
248	func applyCommand(command string, kv map[string]string) (reason string, ok bool) {
249		switch {
250		case strings.HasPrefix(command, "set"):
251			if len(command) == 3 || command[3] != ' ' {
252				return `malformed command: "set" must be followed by exactly one space`, false
253			}
254			rest := command[4:]
255			end := keyEnd(rest)
256			if end == 0 {
257				return "malformed command: empty key", false
258			}
259			if end == len(rest) || rest[end] != '=' {
260				if end < len(rest) && rest[end] != '=' {
261					return "malformed command: key contains whitespace", false
262				}
263				return `malformed command: "set" requires "=" after key`, false
264			}
265			kv[rest[:end]] = rest[end+1:]
266			return "", true
267		case strings.HasPrefix(command, "delete"):
268			if len(command) == 6 || command[6] != ' ' {
269				return `malformed command: "delete" must be followed by exactly one space`, false
270			}
271			rest := command[7:]
272			end := keyEnd(rest)
273			if end == 0 {
274				return "malformed command: empty key", false
275			}
276			if end < len(rest) {
277				if rest[end] == '=' {
278					return `malformed command: key contains "="`, false
279				}
280				return "malformed command: key contains whitespace", false
281			}
282			delete(kv, rest)
283			return "", true
284		default:
285			return `malformed command: expected "set <key>=<value>" or "delete <key>"`, false
286		}
287	}
288	
289	// keyEnd 返回键的结束位置（字节偏移）：第一个 '=' 或空白的位置，
290	// 或整个字符串长度（二者皆无）。
291	func keyEnd(s string) int {
292		for i, r := range s {
293			if r == '=' || unicode.IsSpace(r) {
294				return i
295			}
296		}
297		return len(s)
298	}
299	
300	func newReplicateState(initial InitialState) (replicateState, error) {
301		if initial.CurrentTerm < 0 {
302			return replicateState{}, fmt.Errorf("invalid initial state: currentTerm must be a non-negative integer")
303		}
304		if initial.CommittedIndex < 0 {
305			return replicateState{}, fmt.Errorf("invalid initial state: committedIndex must be a non-negative integer")
306		}
307		if initial.CommittedIndex > len(initial.Log) {
308			return replicateState{}, fmt.Errorf("invalid initial state: committedIndex %d exceeds log length %d", initial.CommittedIndex, len(initial.Log))
309		}
310		log := append([]LogEntry(nil), initial.Log...)
311		for i, entry := range log {
312			expected := i + 1
313			if entry.Index != expected {
314				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-consecutive index %d", expected, entry.Index)
315			}
316			if entry.Term <= 0 {
317				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-positive term %d", expected, entry.Term)
318			}
319			if i > 0 && entry.Term < log[i-1].Term {
320				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d is lower than previous term %d", expected, entry.Term, log[i-1].Term)
321			}
322			if entry.Term > initial.CurrentTerm {
323				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d exceeds currentTerm %d", expected, entry.Term, initial.CurrentTerm)
324			}
325		}
326		return replicateState{
327			currentTerm:    initial.CurrentTerm,
328			committedIndex: initial.CommittedIndex,
329			log:            log,
330		}, nil
331	}
332	
333	// termAt 返回索引 idx 处条目的任期；idx 为 0 时是日志起点哨兵，超出日志长度时 ok 为 false。
334	func (s *replicateState) termAt(idx int) (term int, ok bool) {
335		switch {
336		case idx == 0:
337			return 0, true
338		case idx < 0 || idx > len(s.log):
339			return 0, false
340		default:
341			return s.log[idx-1].Term, true
342		}
343	}
344	
345	// apply 处理单条请求。整个操作是原子的：任何拒绝都不会在日志、已提交索引上
346	// 留下部分变更；唯一例外是较高任期带来的 currentTerm 更新，按规则必须保留。
347	func (s *replicateState) apply(request AppendRequest) AppendResult {
348		snapshot := *s
349		accepted, reason := s.tryApply(request)
350		if !accepted {
351			// 回滚日志与提交位置；较高任期更新（若已发生）保留在 s.currentTerm 中。
352			s.log = snapshot.log
353			s.committedIndex = snapshot.committedIndex
354		}
355		return AppendResult{
356			Accepted:       accepted,
357			Reason:         reason,
358			Term:           s.currentTerm,
359			CommittedIndex: s.committedIndex,
360		}
361	}
362	
363	func (s *replicateState) tryApply(request AppendRequest) (bool, string) {
364		// 规则 1：先做字段合法性校验。违反字段规则的请求只记录拒绝、不改变任何
365		// 状态——即使它携带更高任期，也不能更新节点。
366		if reason := validateRequest(request); reason != ReasonOK {
367			return false, reason
368		}
369	
370		// 规则 2：较低任期直接拒绝，状态（含任期）完全不变。
371		if request.Term < s.currentTerm {
372			return false, ReasonStaleTerm
373		}
374	
375		// 规则 3：首条目任期不得低于前一条日志任期（整段日志必须不下降）。
376		// 这仍属于字段规则，放在任期更新之前：非法请求不能借高任期改变节点。
377		if len(request.Entries) > 0 && request.Entries[0].Term < request.PrevLogTerm {
378			return false, ReasonEntryTermDecreases
379		}
380	
381		// 规则 4：较高任期先更新当前任期，再核对日志；之后即便因前缀不匹配被拒，
382		// 任期更新也保留。
383		if request.Term > s.currentTerm {
384			s.currentTerm = request.Term
385		}
386	
387		// 规则 5：前一条日志必须存在且任期相同。索引 0 始终只与任期 0 匹配。
388		prevTerm, ok := s.termAt(request.PrevLogIndex)
389		if !ok || prevTerm != request.PrevLogTerm {
390			return false, ReasonPrevLogMismatch
391		}
392	
393		// 规则 6：把待追加条目与现有位置逐一比对——全部检查通过后才落笔，
394		// 保证“即使前面已发现可追加内容，也不能留下部分变更”。第一个任期冲突
395		// 位置之后的旧日志都会被整段替换，因此只需在冲突位置之前检查命令冲突。
396		// matched 是请求条目中与现有位置完全相同（同任期同命令）的连续前缀长度；
397		// 超出本地日志长度的位置尚不存在，不属于已匹配，稍后追加。
398		start := request.PrevLogIndex // entries[k] 对应索引 start+1+k
399		cutAt := -1                   // 首个任期不同的现有位置（切片下标）
400		matched := 0
401		for offset, incoming := range request.Entries {
402			idx := start + 1 + offset
403			if idx > len(s.log) {
404				break // 该位置及之后都不存在：稍后整体追加
405			}
406			existing := s.log[idx-1]
407			switch {
408			case existing.Term == incoming.Term && existing.Command == incoming.Command:
409				// 完全相同：保留，重复请求不会产生重复条目。
410				matched++
411			case existing.Term == incoming.Term:
412				// 同索引同任期却命令不同：拒绝，日志与提交位置保持原样。
413				return false, ReasonCommandConflictSameTerm
414			case idx <= s.committedIndex:
415				// 不同任期意味着要覆盖该处及其后缀；已提交条目不可覆盖。
416				return false, ReasonWouldOverwriteCommitted
417			default:
418				// 未提交位置上的任期冲突：截断到此处再追加，其后旧日志整段丢弃。
419				cutAt = idx - 1
420			}
421			if cutAt >= 0 {
422				break
423			}
424		}
425	
426		// 规则 7：合并日志。全部匹配的短请求（matched == len(entries)）不删除
427		// 本地多出的尾部；任期冲突时截断冲突位置及其后缀；其余缺失位置追加。
428		if cutAt >= 0 {
429			matched = cutAt - start
430			s.log = append([]LogEntry(nil), s.log[:cutAt]...)
431		}
432		if matched < len(request.Entries) {
433			s.log = append(s.log, request.Entries[matched:]...)
434		}
435	
436		// 规则 8：提交位置推进至 leaderCommit 与本次确认的最后索引的较小值，
437		// 且不会后退。空条目请求的确认位置就是前一条索引。
438		lastIndex := request.PrevLogIndex + len(request.Entries)
439		newCommit := request.LeaderCommit
440		if lastIndex < newCommit {
441			newCommit = lastIndex
442		}
443		if newCommit > s.committedIndex {
444			s.committedIndex = newCommit
445		}
446		return true, ReasonOK
447	}
448	
449	func validateRequest(request AppendRequest) string {
450		if request.Term < 0 {
451			return ReasonRequestTermNegative
452		}
453		if request.PrevLogIndex < 0 {
454			return ReasonPrevLogIndexNegative
455		}
456		if request.PrevLogTerm < 0 {
457			return ReasonPrevLogTermNegative
458		}
459		if request.LeaderCommit < 0 {
460			return ReasonLeaderCommitNegative
461		}
462		// 条目必须从前一条索引加 1 开始连续排列；任期为正、沿请求条目自身
463		// 不下降，且不得超过请求（领导者）任期。与 prevLogTerm 的衔接在
464		// tryApply 中单独检查。索引 0 是哨兵，真实条目索引必为正。
465		for i, entry := range request.Entries {
466			if entry.Index != request.PrevLogIndex+1+i {
467				return ReasonEntryIndexGap
468			}
469			if entry.Term <= 0 {
470				return ReasonEmptyEntryTerm
471			}
472			if i > 0 && entry.Term < request.Entries[i-1].Term {
473				return ReasonEntryTermDecreases
474			}
475			if entry.Term > request.Term {
476				return ReasonEntryTermExceedsReqTerm
477			}
478		}
479		return ReasonOK
480	}
481

